"""Part two transcription, separate source file and PDF page numbering."""
P2_SOURCE = next((ROOT/'علوم تشریح سر و گردن').glob('جلسه 4*/*پارت_دوم*.pdf'))
P2_DOC = pymupdf.open(P2_SOURCE)
p2_index=json.loads(INDEX.read_text(encoding='utf-8'))
p2_index['assets']=[a for a in p2_index['assets'] if not a.get('asset_id','').startswith('hn04_p2_')]
p2assets={}
for page,ordinal,name in [(2,2,'inferior_base'),(9,2,'petrous_jugular'),(9,3,'canaliculi'),(10,2,'occipital_base'),(10,3,'cranial_deformities'),(11,2,'hydrocephaly'),(11,3,'microcephaly'),(11,4,'wormian_bones'),(12,2,'lefort1'),(12,3,'lefort2'),(13,2,'lefort3')]:
 b=[b for b in P2_DOC[page-1].get_text('dict')['blocks'] if b['type']==1][ordinal]
 im=Image.open(io.BytesIO(b['image'])).convert('RGB'); out=ROOT/f'headneck/images/hn04_p2_{name}.jpeg'; im.save(out,quality=94,optimize=True)
 p2assets[name]=str(out.relative_to(ROOT))
 p2_index['assets'].append(dict(asset_id=out.stem,book='lecture',session='hn04',source_file=str(P2_SOURCE.relative_to(ROOT)),part=2,page=page,bbox=[round(v,2) for v in b['bbox']],w=im.width,h=im.height,bytes=out.stat().st_size,path=p2assets[name]))
INDEX.write_text(json.dumps(p2_index,ensure_ascii=False,indent=1)+'\n',encoding='utf-8')
def p2(text,page): return {'type':'p','text':text,'src':f'جزوهٔ درس، بخش ۲، صفحهٔ PDF {page}'}
def plate2(name,page,title,view,description,labels):
 return {'type':'plate','book':'lecture','asset':p2assets[name],'title':title,'citation':f'جزوهٔ درس، بخش ۲، ص {page} از فایل PDF','view':view,'fa_text':description,'labels':labels,'src':f'جزوهٔ درس، بخش ۲، صفحهٔ PDF {page}','max_h':115,'fresh':False}
def topic2(n,title,pages,gist,question,body):
 meta,content=topic(n,title,[100+x for x in pages],gist,question,body)
 footer='جزوهٔ درس، بخش ۲، صفحهٔ PDF '+ '، '.join(map(str,pages))
 content['blocks'][0]['footer']=footer;content['blocks'][-1]['sources']=footer
 return meta,content
